<?php require_once __DIR__.'/includes/auth.php';if(!empty($_SESSION['user_id']))redirect('dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=strtolower(trim($_POST['email']??''));$password=$_POST['password']??'';$ip=$_SERVER['REMOTE_ADDR']??'unknown';$s=$pdo->prepare('SELECT COUNT(*) FROM login_attempts WHERE ip_address=? AND attempted_at > DATE_SUB(NOW(), INTERVAL 15 MINUTE) AND success=0');$s->execute([$ip]);if($email===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$password===''||strlen($password)>72)$error='Enter a valid email address and your password.';elseif((int)$s->fetchColumn()>=10)$error='Too many login attempts. Please wait 15 minutes.';else{$s=$pdo->prepare('SELECT * FROM users WHERE email=? AND is_active=1');$s->execute([$email]);$u=$s->fetch();$ok=$u&&password_verify($password,$u['password_hash']);$s=$pdo->prepare('INSERT INTO login_attempts(ip_address,email,success) VALUES(?,?,?)');$s->execute([$ip,$email,$ok?1:0]);if($ok){session_regenerate_id(true);$_SESSION['user_id']=(int)$u['id'];$_SESSION['user_name']=$u['name'];$_SESSION['user_email']=$u['email'];redirect('dashboard.php');}$error='Email or password is incorrect.';}}$pageTitle='Log in';require __DIR__.'/includes/header.php'; ?>
<div class="auth-wrap"><div class="auth-card"><span class="eyebrow">Welcome back</span><h1 class="h2 mt-3">Log in to CampusPass</h1><p class="muted">Your next event is just a few clicks away.</p><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><form method="post" data-validate novalidate><?=csrf_field()?><div class="mb-3"><label class="form-label" for="email">Email address</label><input class="form-control" id="email" type="email" name="email" required maxlength="120" autocomplete="email" value="<?=e($_POST['email']??'')?>"></div><div class="mb-4"><label class="form-label" for="password">Password</label><input class="form-control" id="password" type="password" name="password" required maxlength="72" autocomplete="current-password"></div><button class="btn btn-primary w-100">Log in</button></form><p class="text-center mt-4 mb-0 muted">New here? <a href="register-account.php">Create an account</a></p></div></div><?php require __DIR__.'/includes/footer.php'; ?>
